import unittest

def detect_bug(driver):
    try:
        page = driver.page_source.lower()
        keywords = ["error", "invalid", "failed", "exception"]

        for word in keywords:
            if word in page:
                return True, word

        return False, None

    except:
        return False, "browser_closed"

class TestDetectBug(unittest.TestCase):

    def test_happy_path_error_keyword(self):
        class MockDriver:
            page_source = "<html><body>error</body></html>"

        driver = MockDriver()
        expected_result = (True, "error")
        self.assertEqual(detect_bug(driver), expected_result)

    def test_edge_case_no_keywords(self):
        class MockDriver:
            page_source = "<html><body>no error here</body></html>"

        driver = MockDriver()
        expected_result = (False, None)
        self.assertEqual(detect_bug(driver), expected_result)

    def test_error_handling_browser_closed(self):
        class MockDriver:
            page_source = ""

        driver = MockDriver()
        expected_result = (False, "browser_closed")
        self.assertEqual(detect_bug(driver), expected_result)

if __name__ == '__main__':
    unittest.main()
```

