import unittest

def is_driver_alive(driver):
    try:
        driver.current_url
        return True
    except:
        return False

class TestIsDriverAlive(unittest.TestCase):

    def test_happy_path(self):
        class MockDriver:
            current_url = "http://example.com"

        driver = MockDriver()
        expected_result = True
        self.assertEqual(is_driver_alive(driver), expected_result)

    def test_edge_case_no_current_url(self):
        class MockDriver:
            pass

        driver = MockDriver()
        expected_result = False
        self.assertEqual(is_driver_alive(driver), expected_result)

if __name__ == '__main__':
    unittest.main()
```

